mapper.sql:
SELECT source_keys.marketplace, source_keys.seller_name FROM ( SELECT i.marketplace COLLATE utf8mb4_unicode_ci AS marketplace, i.seller_name COLLATE utf8mb4_unicode_ci AS seller_name FROM sellersprite_request_item i JOIN sellersprite_request_run r ON r.run_id = i.run_id WHERE i.seller_name IS NOT NULL AND TRIM(i.seller_name) != ''
AND i.marketplace = #{marketplace}
AND ( COALESCE(i.request_dispatched, 0) = 1 OR i.status IN ('SUCCESS', 'PARTIAL_SUCCESS') OR (r.status IN ('PENDING', 'RUNNING', 'PAUSED', 'PAUSED_SYSTEM') AND i.status IN ('PENDING', 'RUNNING', 'WAITING_RETRY')) ) GROUP BY i.marketplace, i.seller_name UNION ALL SELECT f.marketplace COLLATE utf8mb4_unicode_ci, f.seller_name COLLATE utf8mb4_unicode_ci FROM shop_fetch_run f WHERE f.status IN ('SUCCESS', 'PARTIAL_SUCCESS')
AND f.marketplace = #{marketplace}
GROUP BY f.marketplace, f.seller_name UNION ALL SELECT p.marketplace COLLATE utf8mb4_unicode_ci, p.seller_name COLLATE utf8mb4_unicode_ci FROM shop_products p WHERE p.seller_name IS NOT NULL AND TRIM(p.seller_name) != ''
AND p.marketplace = #{marketplace}
GROUP BY p.marketplace, p.seller_name ) source_keys GROUP BY source_keys.marketplace, source_keys.seller_name

c.seller_name IS NOT NULL
AND LOWER(TRIM(c.seller_name)) NOT IN ('', 'amazon', 'null')

    AND c.marketplace = #{marketplace}


    AND c.batch_code = #{batchCode}


    AND c.source_type = #{sourceType}


    AND c.source_code = #{sourceCode}


    AND c.status = #{status}


    AND c.hit_count >= #{minHitCount}


    AND c.seller_name LIKE CONCAT('%', #{sellerName}, '%')

